"""Construction (建設) — isi bab-bab yang SAMA di tiga buku (Sipil, Bangunan, Lifeline & Peralatan): Bab 1, 2, 4, 6.1, 7 serta ringkasan Bab 3.
Ringkasan + soal ditulis Shirose berdasarkan buku modul bahasa Indonesia (bukan terjemahan resmi). Halaman diisi per-buku di construction.py."""
NOTE = "Ringkasan ditulis Shirose berdasarkan buku modul (bukan terjemahan resmi). Baca teks asli pada halaman buku di bawah."
def C(ti, tj, full, core, points, avoid, exam, soal):
    return dict(ti=ti, tj=tj, full=full + [{"note": NOTE}], summary=dict(core=core, points=points, avoid=avoid, exam=exam), soal=soal)

